$port=8080;$root="c:\Users\Yakob\Documents\portfolio";
# Find a free port starting from $port
while($true){try{$t=New-Object System.Net.Sockets.TcpListener([System.Net.IPAddress]::Loopback,$port);$t.Start();$t.Stop();break}catch{$port++}};
$url="http://localhost:"+$port+"/";$l=New-Object System.Net.HttpListener;$l.Prefixes.Add($url);$l.Start();Write-Host "http://localhost:$port" -ForegroundColor Green;$m=@{".html"="text/html;charset=utf-8";".css"="text/css";".js"="application/javascript";".png"="image/png";".jpg"="image/jpeg";".jpeg"="image/jpeg";".gif"="image/gif";".svg"="image/svg+xml";".mp4"="video/mp4";".woff2"="font/woff2";".woff"="font/woff"};try{while($l.IsListening){$ctx=$l.GetContext();$req=$ctx.Request;$res=$ctx.Response;$p=$req.Url.LocalPath.TrimStart("/");if([string]::IsNullOrEmpty($p)){$p="index.html"};$f=[IO.Path]::Combine($root,$p.Replace("/",[IO.Path]::DirectorySeparatorChar));if([IO.File]::Exists($f)){$e=[IO.Path]::GetExtension($f).ToLower();$ct=if($m.ContainsKey($e)){$m[$e]}else{"application/octet-stream"};$b=[IO.File]::ReadAllBytes($f);$res.StatusCode=200;$res.ContentType=$ct;$res.ContentLength64=$b.Length;$res.OutputStream.Write($b,0,$b.Length);Write-Host "200 $($req.Url.LocalPath)"}else{$b=[Text.Encoding]::UTF8.GetBytes("<h1>404</h1>");$res.StatusCode=404;$res.ContentType="text/html";$res.ContentLength64=$b.Length;$res.OutputStream.Write($b,0,$b.Length);Write-Host "404 $($req.Url.LocalPath)" -ForegroundColor Red};$res.OutputStream.Close()}}finally{$l.Stop()}